    "content": "11月17日，耐克集团在2026年投资者日正式发布“全速前进”长期增长战略，提出“创新突破”（EPIC）、“深度连接”（CONNECTED）及“快速行动”（FAST）三大战略举措。耐克将进一步聚焦五大专业运动，加速推动突破性技术向可扩展的创新平台发展，让创新成果服务更多运动员和运动场景。同时，耐克将推动决策权与资源更加贴近重点国家和城市，通过本地运动员洞察优化产品组合、品牌体验及零售运营，并运用数据、技术和人工智能提升产品创造及市场响应效率。耐克表示，将继续推进大中华区业务调整，推动长期可持续盈利增长。"
