    "description": "这个游戏的灵感是来源于魔兽地图,kk 平台有很多这种割草的类型,我以前也玩过手游的蔚蓝星球,我当时想的是,既然玩魔兽的人这么多,那移植到手机上,不是更爽,随时随地来一把. 中途的波折不谈,但从结果来看,还是我欠缺经验了. 首先是资源过大的问题,因为我想做类似于的魔兽 2.6d 视角,最后发现和 3d 没区别了,里面所有的怪物,角色,都需要 3d 模型,ui,物品图片虽然在手机上显示的小,但是根据屏幕大小,分辨率的不同,真弄低像素的,有的…",
    "content": "这个游戏的灵感是来源于魔兽地图,kk 平台有很多这种割草的类型,我以前也玩过手游的蔚蓝星球,我当时想的是,既然玩魔兽的人这么多,那移植到手机上,不是更爽,随时随地来一把. 中途的波折不谈,但从结果来看,还是我欠缺经验了. 首先是资源过大的问题,因为我想做类似于的魔兽 2.6d 视角,最后发现和 3d 没区别了,里面所有的怪物,角色,都需要 3d 模型,ui,物品图片虽然在手机上显示的小,但是根据屏幕大小,分辨率的不同,真弄低像素的,有的设备就看着糊,噪点多.我基本都是 ui 升 4k 然后压缩的,现在看也没必要 4…"
