    "author": "",
    "description": "台湾“音乐教父”罗大佑炮轰台湾执政的民进党的种种做法“成为台湾民众恐惧的来源”，大陆国台办发言人陈斌华对此评论，当一位以创作《明天会更好》等脍炙人口歌曲而闻名的音乐人对今天台湾社会文化乱象痛心疾首、慷慨陈词，可见问题之严重。 罗大佑上个星期二（11月10日）接受媒体人唐湘龙的广播节目专访时，谈及台湾政治、选举及文化环境，称过去声称要争取人权、民主与言论自由的民进党，取得政权后却成为台湾民众恐惧的来源，并批评民进党执政使台湾文化水平下降。…",
    "content": "台湾“音乐教父”罗大佑炮轰台湾执政的民进党的种种做法“成为台湾民众恐惧的来源”，大陆国台办发言人陈斌华对此评论，当一位以创作《明天会更好》等脍炙人口歌曲而闻名的音乐人对今天台湾社会文化乱象痛心疾首、慷慨陈词，可见问题之严重。 罗大佑上个星期二（11月10日）接受媒体人唐湘龙的广播节目专访时，谈及台湾政治、选举及文化环境，称过去声称要争取人权、民主与言论自由的民进党，取得政权后却成为台湾民众恐惧的来源，并批评民进党执政使台湾文化水平下降。 他也称台湾前总统蔡英文、现任副总统萧美琴等人没有子女，认为她们不会为下一代着想…"
