    "content": "11月18日，国务院台办举行例行新闻发布会。有记者问，台陆委会主委邱垂正近日称，大陆将政治目的纳入交流活动，增加两岸正常往来的风险，两岸交流应“去统战化、去政治化、去风险化”。请问对此有何评论？ 发言人陈斌华答问表示，民进党当局对两岸交流蓄意抹黑，目的是要阻断两岸交流，升高两岸对立对抗。统战的本质是大团结大联合，是交朋友、促团结，是求同存异、共谋发展。对台工作光明正大，大陆出台惠台利民政策、畅通经贸合作渠道、便利两岸人员往来，都是为台湾同胞谋福祉的实事。民进党当局上台以来，顽固谋“独”挑衅，推动与大陆“脱钩断链少流…"
