    "content": "新华社蒙得维的亚11月17日电（记者张铎）中国-乌拉圭全球治理、多边主义与南南合作对话会17日在位于蒙得维的亚的乌拉圭国会举行。与会乌方人士表示，全球局势正在发生深刻变化，多边主义、全球治理和发展中国家间合作重要性越发凸显。 本次活动由中国驻乌拉圭大使馆和乌拉圭国会乌中议会友好小组共同组织。乌拉圭副总统高斯在致辞中指出，乌拉圭坚定支持以联合国为核心的国际体系和以国际法为基础的国际秩序。 乌拉圭外交部长卢贝特金发言表示，乌中关系不仅具有双边意义，也具有重要的地区和全球意义，为不同国情、不同政治制度国家间深化理解与合作…"
