    "title": "习近平：“十五五”规划是中国面向全球工商界发出的合作邀约",
    "link": "https://36kr.com/newsflashes/4074658316882823?f=rss",
    "pub_date": "2026-11-18 10:36:47",
    "author": "",
    "description": "11月18日上午，国家主席习近平在深圳出席2026年亚太经合组织工商领导人峰会开幕式并发表主旨演讲。习近平指出，中国“十五五”规划既是自身的发展蓝图，也为亚太乃至全球经济增长提供机遇清单，是中国面向全球工商界发出的合作邀约。中国将为全球工商界提供超大规模的开放市场，中国正在加快建设开放大市场，扩大优质产品和服务进口，将不断催生多样化新需求。中国将为全球工商界提供互促共进的合作环境。面对单边主义、保护主义冲击，中国始终践行真正的多边主义，…",
    "content": "11月18日上午，国家主席习近平在深圳出席2026年亚太经合组织工商领导人峰会开幕式并发表主旨演讲。习近平指出，中国“十五五”规划既是自身的发展蓝图，也为亚太乃至全球经济增长提供机遇清单，是中国面向全球工商界发出的合作邀约。中国将为全球工商界提供超大规模的开放市场，中国正在加快建设开放大市场，扩大优质产品和服务进口，将不断催生多样化新需求。中国将为全球工商界提供互促共进的合作环境。面对单边主义、保护主义冲击，中国始终践行真正的多边主义，坚定维护多边贸易体制，维护世贸组织规则，推动世界贸易组织改革，不断为世界经济增长…"
