    "content": "新华社布宜诺斯艾利斯11月17日电（记者王钟毅）阿根廷外交部17日发表声明，抗议英国安妮公主在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）和南乔治亚岛进行官方活动，并表示这是一种挑衅。 声明说，英国正非法单方面推进对相关海域碳氢化合物资源的开发。为此，阿根廷已根据《联合国海洋法公约》启动仲裁程序，并向国际海洋法法庭申请采取紧急措施。 声明表示，阿根廷呼吁英国根据联合国大会第2065号决议以及联合国其他相关决议，重启主权问题谈判。 据阿根廷媒体报道，安妮公主当地时间11月9日抵达马岛，开始为期11天的访问。 阿根廷和…"
