    "content": "新华社深圳11月18日电（记者潘洁、肖思思）11月18日上午，国家主席习近平在深圳出席2026年亚太经合组织工商领导人峰会开幕式并发表主旨演讲。 习近平指出，中国“十五五”规划既是自身的发展蓝图，也为亚太乃至全球经济增长提供机遇清单，是中国面向全球工商界发出的合作邀约。 中国将为全球工商界提供超大规模的开放市场。中国拥有全球规模最大的中等收入群体，投资和消费潜力巨大。从新能源汽车到智能家居，从银发经济到冰雪旅游，每一个新赛道都为全球企业带来新机遇。中国正在加快建设开放大市场，扩大优质产品和服务进口，将不断催生多样化…"
