    "description": "这是2022年6月29日拍摄的海南热带雨林国家公园霸王岭片区。新华社记者 张丽芸 摄 凌晨4点半，海南热带雨林深处的霸王岭还笼罩在浓得化不开的夜色里。这个时间，是海南长臂猿监测队员们熟悉的出发时刻。队员们拎着手电筒，光柱贴着山路往前探，刻意放轻脚步——常年“追猿”的人都清楚，喧哗声会惊走树冠上的猿群。 天光伴着猿鸣一同漫进山谷。先是一声短促的低吟，像是试探；接着，音调一路拔高，化作长啸；母猿、亚成猿、幼猿相继应和，清亮的鸣唱越过沟谷，能…",
    "content": "这是2022年6月29日拍摄的海南热带雨林国家公园霸王岭片区。新华社记者 张丽芸 摄 凌晨4点半，海南热带雨林深处的霸王岭还笼罩在浓得化不开的夜色里。这个时间，是海南长臂猿监测队员们熟悉的出发时刻。队员们拎着手电筒，光柱贴着山路往前探，刻意放轻脚步——常年“追猿”的人都清楚，喧哗声会惊走树冠上的猿群。 天光伴着猿鸣一同漫进山谷。先是一声短促的低吟，像是试探；接着，音调一路拔高，化作长啸；母猿、亚成猿、幼猿相继应和，清亮的鸣唱越过沟谷，能传出两三公里。这是热带雨林旗舰物种海南长臂猿标志性的“晨唱”。在全球现存的20种…"
