    "description": "卖火锅、卖麻花、卖冰箱贴，曾是不少人对重庆渝中区的刻板印象。 如今，在这个面积仅23.24平方公里（水陆域面积23.24平方公里，其中陆地面积20.08平方公里）、城镇化率100%的老城区，游客可以买沉浸式体验、居民可以买普惠化便民服务、企业可以买专业化服务。现代服务业成为老城向上的新引擎。 今年前三季度，渝中区第三产业增加值1328.4亿元、同比增长7.1%。一个新增空间有限、几乎没有制造业的老城，服务业在哪里发展、靠什么发展、又怎样…",
    "content": "卖火锅、卖麻花、卖冰箱贴，曾是不少人对重庆渝中区的刻板印象。 如今，在这个面积仅23.24平方公里（水陆域面积23.24平方公里，其中陆地面积20.08平方公里）、城镇化率100%的老城区，游客可以买沉浸式体验、居民可以买普惠化便民服务、企业可以买专业化服务。现代服务业成为老城向上的新引擎。 今年前三季度，渝中区第三产业增加值1328.4亿元、同比增长7.1%。一个新增空间有限、几乎没有制造业的老城，服务业在哪里发展、靠什么发展、又怎样走出去？答案写在楼宇中、产业融合里、开放之路上。 一栋楼就是一条链 “隔壁串个门…"
