    "description": "走进位于贵州省遵义市播州区的贵州航鹏新材料科技有限公司，各式各样的铝制轮毂等汽车零部件整整齐齐地摆放在生产车间。要不了多久，这些产品就会通过物流发往国内外市场。 生产这些汽车零部件的铝，绝大部分来自遵义的本土企业。 遵义作为革命老区，辖区内铝土矿资源丰富，目前全市已探明铝土矿储量约8.1亿吨。过去，这些铝土矿被开采出来后，加工成铝锭后就外销，产业链短、产品附加值也相对较低。 近年来，遵义依托本地优质铝资源，搭建起从铝水原材料到终端产品的…",
    "content": "走进位于贵州省遵义市播州区的贵州航鹏新材料科技有限公司，各式各样的铝制轮毂等汽车零部件整整齐齐地摆放在生产车间。要不了多久，这些产品就会通过物流发往国内外市场。 生产这些汽车零部件的铝，绝大部分来自遵义的本土企业。 遵义作为革命老区，辖区内铝土矿资源丰富，目前全市已探明铝土矿储量约8.1亿吨。过去，这些铝土矿被开采出来后，加工成铝锭后就外销，产业链短、产品附加值也相对较低。 近年来，遵义依托本地优质铝资源，搭建起从铝水原材料到终端产品的完整产业链，主营高端汽车铝制零部件，同时布局汽车电动踏板、电池箱体、电控箱等全系…"
