    "description": "新华社开普敦11月17日电（记者王晓梅 王雷）2026年非洲科技节17日在南非开普敦国际会议中心开幕，来自全球科技和通信行业的决策者、企业家、投资者和创新人士齐聚一堂，探讨人工智能（AI）时代的非洲数字化转型。 今年的非洲科技节是第29届，以“推动非洲数字化转型”为主题，将持续至19日，共吸引来自130多个国家和地区的2000多家企业和超过1.35万人参与。 本届非洲科技节设置通信与连接、数据中心、人工智能、网络安全、初创企业、数字化转…",
    "content": "新华社开普敦11月17日电（记者王晓梅 王雷）2026年非洲科技节17日在南非开普敦国际会议中心开幕，来自全球科技和通信行业的决策者、企业家、投资者和创新人士齐聚一堂，探讨人工智能（AI）时代的非洲数字化转型。 今年的非洲科技节是第29届，以“推动非洲数字化转型”为主题，将持续至19日，共吸引来自130多个国家和地区的2000多家企业和超过1.35万人参与。 本届非洲科技节设置通信与连接、数据中心、人工智能、网络安全、初创企业、数字化转型六大内容板块，除传统的科技和通信展之外，还包括主题演讲、专题讨论、行业研讨会、…"
