    "content": "新华社深圳11月18日电（记者邵艺博、王军伟）11月18日上午，国家主席习近平在深圳出席2026年亚太经合组织工商领导人峰会开幕式并发表主旨演讲。他指出，亚太经合组织伴随经济全球化浪潮而生，推动亚太地区引领时代风气之先。中国愿同各方一道，坚定信心、勇毅前行，携手建设亚太共同体，促进亚太共同繁荣。 ——要维护和平稳定大局。稳，才能安；安，才能兴。亚太经济保持稳中向好，成为全球经济增长的重要引擎，得益于长期稳定的地区环境。越是外部形势复杂，越要坚定维护战后国际秩序，推进平等有序的世界多极化、普惠包容的经济全球化；越要坚…"
