    "content": "丹麦风机制造商维斯塔斯首席执行官安德森说，欧盟在收紧网络安全规定之际，应考虑禁止在关键能源基础设施中使用含有软件的中国零部件和技术。 据路透社报道，被问及欧洲是否应采取类似中国限制外国技术的规定时，安德森（Henrik Andersen）说：“对于关键基础设施中含有软件的技术或零部件，我认为我们应该非常明确地说‘不，谢谢’。” 他说：“现在建设的能源设施将使用30年至50年，你必须确保自己能够掌控这些设施。” 欧盟正修订网络安全规定及设备在欧洲制造的相关要求，各国政府也正扩建电网，以接入更多可再生能源电力。安德森主…"
