    "title": "代码里明明配置了鉴权，服务却仍暴露公网：Shopify 不再相信代码仓库",
    "link": "https://www.infoq.cn/article/eqUZMBIWrmaH7XxbfGro",
    "pub_date": "2026-11-18 10:00:00",
