    "content": "新华社洛杉矶11月17日电 泛美卫生组织17日宣布，美国、墨西哥和玻利维亚已失去麻疹消除状态认证，不再被认定为“麻疹消除国”。这标志着区域疫情形势进一步恶化，也使美洲地区恢复消除状态面临更大挑战。 泛美卫生组织当天发布公报说，专家委员会近日评估了美洲地区最新流行病学形势并提出建议。泛美卫生组织主任巴尔博萨采纳了该建议，认定麻疹地方性传播已在美国、墨西哥和玻利维亚重新建立，这三个国家因此失去麻疹消除状态认证。 根据专家委员会的判定标准，若同一麻疹病毒基因型和谱系在一个国家不间断传播12个月或更长时间，即被视为重新建立…"
